def reserve_legacy(apps, schema_editor):
    with schema_editor.connection.cursor() as cursor:
        cursor.execute(
            "LOCK TABLE catalog_product, catalog_productvariant, checkout_orderitem, "
            "access_auditevent IN SHARE ROW EXCLUSIVE MODE"
        )
    rows = collect_identifiers(apps, schema_editor.connection)
    Registry = apps.get_model("catalog", "SkuIdentifier")
    Registry.objects.using(schema_editor.connection.alias).bulk_create(
        [Registry(**row) for row in rows]
    )
    maximum = numeric_seed(rows)
    with schema_editor.connection.cursor() as cursor:
        cursor.execute("SELECT setval('catalog_sku_number', %s, %s)", [maximum or 1, bool(maximum)])


def numeric_seed(rows):
    numbers = [
        int(row["code"][4:])
        for row in rows
        if row["code"].startswith("sku-")
        and row["code"][4:].isascii()
        and row["code"][4:].isdigit()
    ]
    maximum = max(numbers, default=0)
    if maximum >= 9223372036854775807:
        raise RuntimeError(
            "Legacy numeric SKUs exhaust the bigint sequence; review before migrating."
        )
    return maximum


def require_empty_registry(apps, schema_editor):
    Registry = apps.get_model("catalog", "SkuIdentifier")
    if Registry.objects.using(schema_editor.connection.alias).exists():
        raise RuntimeError(
            "Cannot reverse SKU issuance history. Retain the registry/sequence "
            "and recover forward; never rewind issued codes."
        )


